EXPLAIN (ANALYZE, BUFFERS)-- search-page::aggregation::manufacturer
	SELECT REPLACE(IFNULL("product"."product_manufacturer_id", "product.parent"."product_manufacturer_id")::text, '-', '') as "manufacturer" FROM "product" LEFT JOIN "product" "product.parent" ON "product"."parent_id" = "product.parent"."id" AND "product"."parent_version_id" = "product.parent"."version_id" LEFT JOIN "product_visibility" "product.visibilities" ON "product"."visibilities" = "product.visibilities"."product_id" AND "product".version_id = "product.visibilities".product_version_id LEFT JOIN "product_search_keyword" "product.searchKeywords" ON "product"."id" = "product.searchKeywords"."product_id" AND "product".version_id = "product.searchKeywords".product_version_id INNER JOIN (SELECT SUM(IF(lower("product.searchKeywords"."keyword") COLLATE ucs_basic = 'organizer' , 1.20000000000000 * "product.searchKeywords"."ranking", 0) + IF(lower("product.searchKeywords"."keyword") COLLATE ucs_basic LIKE '%organizer%' , 1.00000000000000 * "product.searchKeywords"."ranking", 0)) / COUNT(product.id) * (COUNT(DISTINCT "product.searchKeywords"."id")) as _score, "product"."id", "product"."version_id" FROM "product" LEFT JOIN "product" "product.parent" ON "product"."parent_id" = "product.parent"."id" AND "product"."parent_version_id" = "product.parent"."version_id" LEFT JOIN "product_visibility" "product.visibilities" ON "product"."visibilities" = "product.visibilities"."product_id" AND "product".version_id = "product.visibilities".product_version_id LEFT JOIN "product_search_keyword" "product.searchKeywords" ON "product"."id" = "product.searchKeywords"."product_id" AND "product".version_id = "product.searchKeywords".product_version_id WHERE ("product"."version_id" = '0fa91ce3-e96a-4bc2-be4b-d9ce752c3425') AND (((("product.visibilities"."visibility" >= '20') AND "product.visibilities"."sales_channel_id" = '6a6d9237-b4d5-41ac-937b-91b496b4daf3' AND IFNULL("product"."active", "product.parent"."active") = '1') AND ((lower("product.searchKeywords"."keyword") COLLATE ucs_basic IN ('organizer', 'organizer')) AND "product.searchKeywords"."language_id" = '2fbb5fe2-e29a-4d70-aa58-54ce7ce3e20b') AND NOT ("product"."display_group"  IS NOT DISTINCT FROM  NULL))) AND (lower("product.searchKeywords"."keyword") COLLATE ucs_basic = 'organizer' OR lower("product.searchKeywords"."keyword") COLLATE ucs_basic LIKE '%organizer%') GROUP BY "product"."id", "product"."version_id" HAVING (SUM(IF(lower("product.searchKeywords"."keyword") COLLATE ucs_basic = 'organizer' , 1.20000000000000 * "product.searchKeywords"."ranking", 0) + IF(lower("product.searchKeywords"."keyword") COLLATE ucs_basic LIKE '%organizer%' , 1.00000000000000 * "product.searchKeywords"."ranking", 0)) / COUNT(product.id) * (COUNT(DISTINCT "product.searchKeywords"."id"))) >= '1' ORDER BY _score DESC) score_table ON score_table."id" = "product"."id" AND score_table."version_id" = "product"."version_id"  WHERE ("product"."version_id" = '0fa91ce3-e96a-4bc2-be4b-d9ce752c3425') AND (((("product.visibilities"."visibility" >= '20') AND "product.visibilities"."sales_channel_id" = '6a6d9237-b4d5-41ac-937b-91b496b4daf3' AND IFNULL("product"."active", "product.parent"."active") = '1') AND ((lower("product.searchKeywords"."keyword") COLLATE ucs_basic IN ('organizer', 'organizer')) AND "product.searchKeywords"."language_id" = '2fbb5fe2-e29a-4d70-aa58-54ce7ce3e20b') AND NOT ("product"."display_group"  IS NOT DISTINCT FROM  NULL))) GROUP BY IFNULL("product"."product_manufacturer_id", "product.parent"."product_manufacturer_id");
